INSERT INTO evidence_notes(note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES
('N060-01','CN0127','W06S01','设计水量与表间差异','§4.3.2，表4.3-10—13 pp159–165','工艺源强表10167t/a、总12558.1t/a；流程表工艺10231.7、总12623、回用5020、纳管6707、损耗895.9t/a；差异约64.9与64.7蒸汽带入相近但不强认完全同因。地面拖洗表240、正文216；压滤机1.5t/d×264与正文758不闭合。喷淋分项68.4+34=102.4，表102.3。原文保留；分股浓度空白不补猜；MVR冷凝监测表及雨水表未取得数字，截图超时。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N060-02','CN0127','W06S01','膜设计细化','§4.3.2.1、4.3.2.6及表4.3-12','预清洗用压滤液回用水；后续回用水、纯水分开；膜浓缩设计进水8491.7t/a，MVR6133.3t/a、母液干化276t/a；回用水箱5019.9t/a含MVR等支路，不能用总回用除膜进料当膜回收率；膜型号未披露，采购不等于投运。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N060-03','CN0144','S045-08','既有综合站和中试依托','拟批准公示第2项目第2项','既有站400m³/d，调节、厌氧水解、接触氧化、混凝沉淀；一期中试生产废水依托；冷却及纯水浓水另在总排口汇合。此前045未获取本项目水段，本次原文核实。二期回收不在该一期环评范围。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N060-04','CN0304','S060-01','生产项目回用边界','区域削减方案第七节结论','政府公开方案引用生产项目环评预测全废水回用、不外排；并非直接验收证据；内部工艺、废盐、浓水及水量仍待原报告，不能由研发中心RO移植为该生产线。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N060-05','CN0291','S060-03','共享厂区排放边界和整改','§10.5 表10-18/19 pp43–45','2025-06同厂阻燃剂研发登记表称现有工程处理后直排兰江，工业污水厂当时设备安装，拟2025-07试运；相关新项目正式投产前须纳管。2024 DW001 TOC、总氮化物、总铜、锌、镍缺测，计划2025监测；有机磷膜回收为阻燃剂相关拟改造，不能归催化剂废水。2026现行接管待核。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N060-06','CN0308','S060-04','实际危废接收与处置','2024年度公开第一表','HW50 271-006-50接收213.3344t、利用166.87t、年末46.4644t；900-048-50接收1951.6t、利用1890.62t、年末87.82t。全类别接收24508.9939t、利用24873.6189t；不是污水量、催化剂产量或全部贵金属专线。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N060-07','CN0308','S060-04','实际废液及残余物处置','2024年度公开第二表','有机废液900-013-11产生9054.764t、D10自行8982.324t；有机废液-2产生1086.291t、自行1070.291t；HW45反应残液335.8t、残余液3.79t及HW34滤液0.15t均D10；HW18污泥44.56t、委托38.03t、库存6.53t。为全公司危废口径，不能认定该污泥为贵金属专线或污水处理污泥；不将液态危废质量加到废水。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N060-08','CN0257','S060-05','批复及租赁边界','募集说明书1-1-73','项目代码2309-370571-89-01-884375，东开管环审〔2024〕62号原已录。2025-01-01至2029-12-31租用山东银凯电子厂区；截至披露已开工。环保税40万元/年为可研估算，非污水实际成本。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N060-09','CN0257','S060-06','固废鉴别前置条件','询价公告二、三','要求五类固废鉴别方案、检测、报告和备案，以满足验收条件；具体五类表格未得，不猜盐或污泥分类。采购公告并非鉴别结果或环保验收。','WEB_SECONDARY','WEB_TEXT','2026-11-28'),
('N060-10','CN0283','S060-07','专有生产设备采购','2025-11-20公告','拟购4台套搪瓷反应罐、2台套回转窑，供应商拟田中贵金属工业株式会社；复核旧采购同标的，不重复认定合同。项目地址雅安经开区青江路6号；不同日期采购异议联系人不同，不推为污水负责人。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N060-11','CN0310','S060-08','历史批复与产能变化','问询回复8-1-65、8-1-125','2023-06-15吉市环评字〔2023〕32号改变四甲基/四乙基氢氧化铵产能；2021一期20838吨名义规模已建投产，2023报告尚在爬坡。该文件是公司回复而非环评原文，未取得污水内部工艺。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N060-12','CN0230','S060-09','车间收集要求','招标正文URS','吸收塔定期换水管输车间污水收集池，隔离密封、臭气接车间废气处理系统；转载标题与正文不符，按正文保留，未把废气RCO当污水处理。既有污水站设计及中标金额不重复。','WEB_SECONDARY','WEB_TEXT','2026-11-28'),
('N060-13','CN0267','S060-10','项目官方采购阶段','七建官方询比采购','临时办公区、厕所化粪池、围挡等临建项目采购，属施工期公辅设施，不当生产污水系统；采购证明工程阶段，不证明竣工。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N060-14','CN0270','S060-11','独立转移许可','福建2025年11月转出公告第43项','中化泉州石化获批向浙江瑞博宝珞杰转出柴油加氢装置废催化剂240吨（251-016-50），有效至2025-12-31；独立于此前广州石化转移批复，非实际接收。','WEB_PRIMARY','WEB_TEXT','2026-11-28');
